@use '../abstracts' as *;

.c-home { overflow: hidden; color: $black; }
.c-home h1, .c-home h2, .c-home h3, .c-home p { margin: 0; }
.c-home h2 { font-size: 5.2rem; line-height: 1.05; font-weight: 700; }
.c-home-button { display: inline-flex; align-items: center; justify-content: center; gap: 2.2rem; border: 0; border-radius: 5rem; padding: 1.5rem 2.8rem; background: $rudnik-green; color: $white; font-weight: 700; font-size: 1.6rem; text-decoration: none; white-space: nowrap; }
.c-home-button--outline { background: transparent; border: 1px solid $white; }
.c-home-hero { width: min(1840px, calc(100% - 80px)); height: 800px; margin: 0 auto 112px; background-position: center; background-size: cover; border-radius: 2.6rem; position: relative; color: $white; }
