@use '../abstracts' as *;

.c-home { overflow: hidden; color: $black; }
.c-home h1, .c-home h2, .c-home h3, .c-home p { margin: 0; }
.c-home h2 { font-size: 5.2rem; line-height: 1.05; font-weight: 700; }
.c-home-button { display: inline-flex; align-items: center; justify-content: center; gap: 2.2rem; border: 0; border-radius: 5rem; padding: 1.5rem 2.8rem; background: $rudnik-green; color: $white; font-weight: 700; font-size: 1.6rem; text-decoration: none; white-space: nowrap; }
.c-home-button--outline { background: transparent; border: 1px solid $white; }
.c-home-hero { width: min(1840px, calc(100% - 80px)); height: 800px; margin: 0 auto 112px; background-position: center; background-size: cover; border-radius: 2.6rem; position: relative; color: $white; }
.c-home-hero__content { position: absolute; top: 190px; left: clamp(6rem, 8vw, 11.5rem); max-width: 620px; }
.c-home-hero h1 { font-size: 6rem; line-height: 1.1; margin-bottom: 6rem; }
.c-home-benefits { display: grid; min-height: 175px; grid-template-columns: repeat(5, 1fr); align-items: start; text-align: center; margin-bottom: 102px; }
.c-home-benefit img { display: block; width: 60px; height: 60px; object-fit: contain; margin: 0 auto 1.8rem; }
.c-home-benefit p { font-size: 2.5rem; line-height: 1.2; font-weight: 500; }
.c-home-crops { background: $rudnik-light; padding: 8.5rem 0 28.3rem; }
.c-home-crops h2 { font-size: 5.6rem; }.c-home-kicker { margin: 1rem 0 5rem; color: $rudnik-green; font-weight: 700; font-size: 2rem; }
.c-home-crop-group { margin-top: 3rem; }.c-home-crop-group h3 { display: inline-block; min-width: 155px; margin-bottom: 2rem; padding: .7rem 3rem; border-radius: 1.5rem; background: var(--crop-colour); color: $white; text-align: center; font-size: 2rem; }
.c-home-crop-grid { display: flex; flex-wrap: wrap; gap: 1.5rem; }.c-home-crop { display: grid; place-items: center; width: 98px; height: 98px; border: 1px solid #d5d5d5; border-radius: 1.2rem; background: $white; color: $black; font-size: 1.2rem; text-decoration: none; }.c-home-crop img { width: 38px; height: 38px; object-fit: contain; margin-bottom: .5rem; }
.c-home-products { padding-top: 10rem; }.c-home-crops + .c-home-products { margin-top: 88px; }.c-home-products + .c-home-products { margin-top: 88px; }.c-home-products header, .c-home-blog header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 5.5rem; }.c-home-product-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 2.4rem; }
.c-home-card { display: flex; min-height: 510px; flex-direction: column; align-items: center; padding: 2.5rem; border: 1px solid #d3d3d3; border-radius: 3rem; text-align: center; }.c-home-card__image { display: grid; height: 245px; place-items: center; margin-bottom: 2rem; }.c-home-card__image img { max-height: 230px; width: auto; max-width: 100%; object-fit: contain; }.c-home-card h3 { min-height: 48px; padding-top: 1.8rem; border-top: 1px solid #d4d4d4; font-size: 1.9rem; font-weight: 500; }.c-home-card h3 a { color: inherit; text-decoration: none; }.c-home-card__price { margin: 1.5rem 0 2rem; font-size: 2.6rem; font-weight: 700; }.c-home-card__cart { margin-top: auto; padding: 1.2rem 3.4rem; border-radius: 3rem; background: $rudnik-green; color: $white; font-size: 1.5rem; font-weight: 700; text-decoration: none; }
.c-home-catalogues { display: flex; align-items: center; justify-content: space-between; height: 384px; margin-top: 96px; padding: 6.5rem 8rem; overflow: hidden; border-radius: 3rem; background-size: cover; background-position: center; color: $white; }.c-home-catalogues h2 { margin-bottom: 4rem; color: $white; }.c-home-catalogues p { display: flex; gap: 1.5rem; align-items: center; margin-top: 2rem; font-size: 2rem; }.c-home-catalogues p img { width: 24px; height: 24px; }.c-home-catalogues__cover { width: 365px; max-height: 300px; object-fit: contain; align-self: end; }
.c-home-products--recommended { margin-top: 67px; padding-top: 8.5rem; padding-bottom: 19px; }.c-home-about { margin-top: 132px; padding: 12rem 0 14.5rem; background: $rudnik-light; }.c-home-about__grid { display: grid; grid-template-columns: 1fr 1fr; align-items: center; gap: 12rem; }.c-home-about__lead { margin: 4rem 0 2.5rem; font-size: 2.2rem; line-height: 1.35; }.c-home-about__grid > div > div:not(.c-home-about__lead) { margin-bottom: 4rem; font-size: 1.7rem; }.c-home-about__image { width: 100%; height: 585px; border-radius: 3rem; object-fit: cover; }
.c-home-blog { margin-top: 117px; padding: .7rem 0 0; }.c-home-blog__grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2.5rem; }.c-home-blog__grid img { width: 100%; height: 305px; object-fit: cover; border-radius: 3rem; }.c-home-blog__grid time { display: block; margin: 2.2rem 0; font-size: 1.7rem; }.c-home-blog__grid h3 { min-height: 13rem; font-size: 3rem; line-height: 1.2; }.c-home-blog__grid h3 a { color: $black; text-decoration: none; }.c-home-read { display: inline-block; margin-top: 2rem; color: $rudnik-green; font-size: 1.8rem; font-weight: 700; text-decoration: none; }
.c-home-knowledge { min-height: 1273px; margin-top: -46px; padding: 72rem 0 8rem; background-size: cover; background-position: center top; }.c-home-knowledge__items { display: grid; gap: 2rem; }.c-home-knowledge details { padding: 2.8rem 9rem; border: 1px solid $white; border-radius: 2.5rem; background: rgba($rudnik-green-dark, .92); color: $white; }.c-home-knowledge summary { display: flex; justify-content: space-between; cursor: pointer; font-size: 3.7rem; font-weight: 700; }.c-home-knowledge details div { padding-top: 3rem; font-size: 1.7rem; line-height: 1.5; }
